#!/usr/bin/env python3
"""A text-art renderer implemented from the bundled font data and CLI observations."""
import io
import os
import re
import struct
import sys
import zipfile

DEFAULT_DIRECTORY = '/usr/local/share/figlet'
COPYRIGHT = '''FIGlet Copyright (C) 1991-2012 Glenn Chappell, Ian Chai, John Cowan,
Christiaan Keet and Claudio Matsuoka
Internet: <info@figlet.org> Version: 2.2.5, date: 31 May 2012

FIGlet, along with the various FIGlet fonts and documentation, may be
freely copied and distributed.

If you use FIGlet, please send an e-mail message to <info@figlet.org>.

The latest version of FIGlet is available from the web site,
\thttp://www.figlet.org/

'''
REMOVED_F = '''
Because of numerous incompatibilities, the "-F" option has been
removed.  It has been replaced by the "figlist" program, which is now
included in the basic FIGlet package.  "figlist" is also available
from  http://www.figlet.org/under UNIX utilities.
'''


def usage(name):
    return (f'Usage: {name} [ -cklnoprstvxDELNRSWX ] [ -d fontdirectory ]\n'
            '              [ -f fontfile ] [ -m smushmode ] [ -w outputwidth ]\n'
            '              [ -C controlfile ] [ -I infocode ] [ message ]\n')


def atoi(s):
    m = re.match(r'\s*([+-]?\d+)', s)
    if not m:
        return 0
    return (int(m[1]) + 2**31) % 2**32 - 2**31


def number(s):
    m = re.match(r'([+-]?)(0[xX][0-9a-fA-F]+|0[0-7]*|[1-9][0-9]*)', s)
    if not m:
        return None
    t = m[2]
    n = int(t, 16 if t.lower().startswith('0x') else 8 if t.startswith('0') else 10)
    return -n if m[1] == '-' else n


def strip_suffix(name, suffixes):
    if name[-4:].lower() in suffixes:
        return name[:-4]
    return name


class Failure(Exception):
    pass


class Options:
    def __init__(self):
        self.directory = os.environ.get('FIGLET_FONTDIR', DEFAULT_DIRECTORY)
        self.font = 'standard'
        self.controls = []
        self.width = 80
        self.align = 'x'
        self.direction = None
        self.layout = 'default'
        self.paragraph = False
        self.german = False
        self.info = -1
        self.words = []

    def parse(self, args, argv0):
        name = os.path.basename(argv0)
        i = 0
        stopped = False
        while i < len(args):
            arg = args[i]
            i += 1
            if stopped or arg == '-' or not arg.startswith('-'):
                self.words.append(arg)
                if 'POSIXLY_CORRECT' in os.environ:
                    stopped = True
                continue
            if arg == '--':
                stopped = True
                continue
            j = 1
            while j < len(arg):
                ch = arg[j]
                j += 1
                val = None
                if ch in 'dfmwCI':
                    if j < len(arg):
                        val = arg[j:]
                        j = len(arg)
                    elif i < len(args):
                        val = args[i]
                        i += 1
                    else:
                        raise Failure(f"{argv0}: option requires an argument -- '{ch}'\n" + usage(name))
                elif ch not in 'cklnoprstvxDELNRSWXAF':
                    raise Failure(f"{argv0}: invalid option -- '{ch}'\n" + usage(name))
                if ch == 'F':
                    raise Failure(f'{name}: illegal option -- F\n' + usage(name) + REMOVED_F)
                if ch in 'clrx':
                    self.align = ch
                elif ch == 'd':
                    self.directory = val
                elif ch == 'f':
                    self.font = strip_suffix(val, ('.flf', '.tlf'))
                elif ch == 'C':
                    self.controls.append(strip_suffix(val, ('.flc',)))
                elif ch == 'N':
                    self.controls.clear()
                elif ch == 'w':
                    n = atoi(val)
                    if n > 0:
                        self.width = n
                elif ch == 't':
                    try:
                        columns = os.get_terminal_size(0).columns
                        if columns > 0:
                            self.width = columns
                    except OSError:
                        pass
                elif ch in 'np':
                    self.paragraph = ch == 'p'
                elif ch in 'DE':
                    self.german = ch == 'D'
                elif ch in 'LRX':
                    self.direction = {'L': False, 'R': True, 'X': None}[ch]
                elif ch in 'skWSo':
                    self.layout = {'s': 'default', 'k': 'kern', 'W': 'full',
                                   'S': 'smush', 'o': 0}[ch]
                elif ch == 'm':
                    n = atoi(val)
                    self.layout = 'default' if n < -1 else 'full' if n == -1 else 'kern' if n == 0 else n & 63
                elif ch in 'Iv':
                    self.info = 0 if ch == 'v' else atoi(val)
        return self


def open_data(directory, name, extensions, kind):
    for prefix in [directory, '']:
        for suffix in extensions:
            path = os.path.join(prefix, name + suffix) if prefix else name + suffix
            try:
                with open(path, 'rb') as f:
                    data = f.read()
            except OSError:
                continue
            if data.startswith(b'PK\x03\x04'):
                try:
                    with zipfile.ZipFile(io.BytesIO(data)) as archive:
                        data = archive.read(archive.infolist()[0])
                except (OSError, ValueError, zipfile.BadZipFile, IndexError):
                    data = b''
            return data
    raise Failure(f'{name}: Unable to open {kind} file\n')


def font_text(raw):
    """Font cells use UTF-8. An invalid sequence terminates a row."""
    try:
        return raw.decode('utf-8')
    except UnicodeDecodeError as e:
        return raw[:e.start].decode('utf-8')


class Glyph:
    def __init__(self, rows):
        self.rows = rows
        self.width = max(map(len, rows), default=0)


class Font:
    def __init__(self, data, name):
        lines = data.split(b'\n')
        header = lines[0].rstrip(b'\r')
        if not (header.startswith(b'flf2a') or header.startswith(b'tlf2a')) or len(header) < 6:
            raise Failure(f'{name}: Not a FIGlet 2 font file\n')
        self.hardblank = font_text(header[5:6]) or '$'
        values = []
        for value in header[6:].split():
            try:
                values.append(int(value))
            except ValueError:
                break
        if len(values) < 5:
            raise Failure(f'{name}: Not a FIGlet 2 font file\n')
        self.height, self.baseline, self.maxwidth, old, comments = values[:5]
        if self.height < 1 or self.height > 10000:
            raise Failure(f'{name}: Not a FIGlet 2 font file\n')
        self.rtl = bool(values[5]) if len(values) > 5 else False
        full = values[6] if len(values) > 6 else (0 if old < 0 else 64 if old == 0 else 128 | old)
        self.default_mode = 'smush' if full & 128 else 'kern' if full & 64 else 'full'
        self.rules = full & 63
        self.glyphs = {}
        pos = max(0, comments) + 1

        def read_glyph():
            nonlocal pos
            rows = []
            for _ in range(self.height):
                line = lines[pos] if pos < len(lines) else b''
                pos += 1
                line = line.rstrip(b'\r\t ')
                # Endmarks are repeated at the end of the last row.
                if line:
                    end = line[-1:]
                    line = line.rstrip(end)
                rows.append(font_text(line))
            return Glyph(rows)

        codes = list(range(32,127)) + [196,214,220,228,246,252,223]
        for code in codes:
            self.glyphs[code] = read_glyph()
        while pos < len(lines):
            tag = lines[pos].strip().decode('ascii', 'ignore')
            pos += 1
            code = number(tag)
            if code is not None:
                self.glyphs[code] = read_glyph()
        self.empty = Glyph([''] * self.height)

    def get(self, code):
        return self.glyphs.get(code, self.glyphs.get(0, self.empty))


class Renderer:
    def __init__(self, font, options):
        self.font = font
        self.height = font.height
        self.width = options.width
        self.rtl = font.rtl if options.direction is None else options.direction
        self.align = options.align
        if self.align == 'x':
            self.align = 'r' if self.rtl else 'l'
        layout = options.layout
        self.rules = font.rules
        if layout == 'default':
            self.mode = font.default_mode
        elif isinstance(layout, int):
            self.mode, self.rules = 'smush', layout
        else:
            self.mode = layout
        self.output = []

    def smush(self, left, right, wide=True):
        if left == ' ' or not left:
            return right
        if right == ' ' or not right:
            return left
        if self.mode != 'smush' or not wide:
            return None
        hb = self.font.hardblank
        if self.rules == 0:
            if left == hb:
                return right
            if right == hb:
                return left
            return left if self.rtl else right
        if left == hb or right == hb:
            return hb if self.rules & 32 and left == right else None
        if self.rules & 1 and left == right:
            return left
        hierarchy = '|/\\[]{}()<>'
        if self.rules & 2:
            if left == '_' and right in hierarchy:
                return right
            if right == '_' and left in hierarchy:
                return left
        if self.rules & 4:
            groups = ['|', '/\\', '[]', '{}', '()', '<>']
            li = next((i for i,g in enumerate(groups) if left in g), -1)
            ri = next((i for i,g in enumerate(groups) if right in g), -1)
            if li >= 0 and ri >= 0 and li != ri:
                return left if li > ri else right
        if self.rules & 8 and left + right in ['[]', '][', '{}', '}{', '()', ')(']:
            return '|'
        if self.rules & 16:
            return {'/\\': '|', '\\/': 'Y', '><': 'X'}.get(left+right)
        return None

    def join(self, current, glyph, lastwidth):
        rows = glyph.rows
        n = max(map(len, current), default=0)
        w = glyph.width
        if self.rtl:
            left, right = rows, current
            lw, rw = w, n
        else:
            left, right = current, rows
            lw, rw = n, w
        overlap = 0
        if self.mode != 'full':
            overlap = w
            for l, r in zip(left, right):
                # The two occupied edges of this row determine how closely
                # the figures may approach one another.
                le = len(l.rstrip(' '))
                re = len(r) - len(r.lstrip(' '))
                available = lw - le + re
                lc = l[le-1] if le else ''
                rc = r[re:re+1]
                if lc and rc and self.smush(lc, rc, w >= 2 and lastwidth >= 2) is not None:
                    available += 1
                overlap = min(overlap, available)
            overlap = max(0, overlap)
        total = lw + rw - overlap
        merged = []
        for l, r in zip(left, right):
            l = l.ljust(lw)
            r = r.ljust(rw)
            start = lw - overlap
            cells = list(l + ' ' * max(0, rw-overlap))
            if start < 0:
                cells = [' '] * -start + cells
            for j, c in enumerate(r):
                at = start+j
                if at < 0:
                    continue
                if at >= len(cells):
                    cells.extend(' ' * (at-len(cells)+1))
                if at < lw:
                    merged_char = self.smush(cells[at], c, w >= 2 and lastwidth >= 2)
                    if merged_char is not None:
                        cells[at] = merged_char
                else:
                    cells[at] = c
            merged.append(''.join(cells[:total]))
        return merged

    def assemble(self, codes):
        rows = [''] * self.height
        lastwidth = 0
        for c in codes:
            glyph = self.font.get(c)
            if glyph.width:
                rows = self.join(rows, glyph, lastwidth)
                lastwidth = glyph.width
        return rows, lastwidth

    def emit(self, rows):
        n = max(map(len, rows), default=0)
        padding = max(0, (self.width-n)//2) if self.align == 'c' else max(0, self.width-1-n) if self.align == 'r' else 0
        prefix = ' ' * padding
        for row in rows:
            self.output.append(prefix + row.replace(self.font.hardblank, ' ') + '\n')

    def render_line(self, codes, forced=False):
        pending = []
        rows = [''] * self.height
        lastwidth = 0
        produced = False
        skipping_space = False
        for c in codes:
            glyph = self.font.get(c)
            if not glyph.width:
                continue
            if skipping_space and c == 32:
                continue
            skipping_space = False
            while True:
                result = self.join(rows, glyph, lastwidth)
                if max(map(len,result), default=0) < self.width:
                    rows = result
                    pending.append(c)
                    lastwidth = glyph.width
                    break
                if c == 32 and pending:
                    end = len(pending)
                    if any(x != 32 for x in pending):
                        while end and pending[end-1] == 32:
                            end -= 1
                    self.emit(self.assemble(pending[:end])[0])
                    produced = True
                    pending, rows, lastwidth = [], ['']*self.height, 0
                    skipping_space = True
                    break
                # Find the most recent word separator, excluding indentation.
                split = None
                seen_word = False
                for i,x in enumerate(pending):
                    if x == 32:
                        if seen_word and (i == 0 or pending[i-1] != 32):
                            split = i
                    else:
                        seen_word = True
                if split is not None:
                    after = split
                    while after < len(pending) and pending[after] == 32:
                        after += 1
                    self.emit(self.assemble(pending[:split])[0])
                    produced = True
                    pending = pending[after:]
                    rows, lastwidth = self.assemble(pending)
                    continue
                if pending:
                    self.emit(rows)
                    produced = True
                    pending, rows, lastwidth = [], ['']*self.height, 0
                    continue
                # A figure wider than the page is printed without kerning;
                # width one is the special, untruncated, one-figure mode.
                raw = glyph.rows
                if self.width > 1:
                    raw = [s[-(self.width-1):] if self.rtl else s[:self.width-1] for s in raw]
                self.emit(raw)
                produced = True
                skipping_space = True
                break
        if pending:
            self.emit(rows)
        elif forced and not produced:
            self.emit([''] * self.height)

    def render(self, codes):
        line = []
        for c in codes:
            if c == 10:
                self.render_line(line, True)
                line = []
            else:
                line.append(c)
        if line:
            self.render_line(line)
        return ''.join(self.output)


def translate_set(s):
    result = []
    i = 0
    tokens = []
    while i < len(s):
        c = s[i]
        i += 1
        escaped = False
        if c == '\\' and i < len(s):
            escaped = True
            match = re.match(r'[+-]?(?:0[xX][0-9a-fA-F]+|[0-9]+)', s[i:])
            if match:
                t = match[0]
                n = number(t)
                tokens.append((n if n is not None else 0, True))
                i += len(t)
                continue
            c = s[i]
            i += 1
            c = {'n':'\n', 't':'\t', 'r':'\r', 'b':'\b', 'f':'\f', 'v':'\v'}.get(c,c)
        tokens.append((ord(c), escaped))
    i = 0
    while i < len(tokens):
        if i+2 < len(tokens) and tokens[i+1] == (45,False):
            a,b = tokens[i][0], tokens[i+2][0]
            if abs(b-a) < 100000:
                result.extend(range(a,b+1) if a <= b else range(a,b-1,-1))
            i += 3
        else:
            result.append(tokens[i][0])
            i += 1
    return result


class Controls:
    def __init__(self):
        self.maps = []
        self.utf8 = False
        self.hz = False
        self.g = [None, None, None, None]
        self.left = 0
        self.right = 1

    def load(self, data, name):
        text = data.decode('latin1')
        current = {}
        self.maps.append(current)
        for line in text.splitlines():
            s = line.strip()
            if not s or s.startswith('#') or s.startswith('flc2'):
                continue
            words = s.split()
            if words[0] == 'u':
                self.utf8 = True
            elif words[0] == 'h':
                self.hz = True
            elif words[0] == 'f':
                current = {}
                self.maps.append(current)
            elif words[0] == 't' and len(words) >= 3:
                src,dst = translate_set(words[1]),translate_set(words[2])
                for i,c in enumerate(src):
                    if dst:
