                        val = args[i]
                        i += 1
                    else:
                        raise Failure(f"{argv0}: option requires an argument -- '{ch}'\n" + usage(name))
                elif ch not in 'cklnoprstvxDELNRSWXAF':
                    raise Failure(f"{argv0}: invalid option -- '{ch}'\n" + usage(name))
                if ch == 'F':
                    raise Failure(f'{name}: illegal option -- F\n' + usage(name) + REMOVED_F)
                if ch in 'clrx':
