            for mapping in self.maps:
                c=mapping.get(c,c)
            if c==9: c=32
            elif c in [11,12,13]: c=10
            out.append(c)
        if opts.paragraph:
            original=out
            out=[]
            for i,c in enumerate(original):
                if c==10 and (i==0 or original[i-1]!=10) and (i+1==len(original) or original[i+1] not in [10,32]):
                    c=32
                out.append(c)
        return out


def run(args, data, argv0='executable'):
    opts = Options().parse(args, argv0)
    name = os.path.basename(argv0)
    if opts.info >= 0:
        return {0: COPYRIGHT+usage(name), 1:'20205\n', 2:opts.directory+'\n',
                3:opts.font+'\n', 4:str(opts.width)+'\n', 5:'flf2 tlf2\n'}.get(opts.info,'')
    try:
        controls = Controls()
        for c in opts.controls:
            controls.load(open_data(opts.directory,c,['.flc'],'control'),c)
        font = Font(open_data(opts.directory,opts.font,['.flf','.tlf'],'font'),opts.font)
    except Failure as e:
        raise Failure(name+': '+str(e))
    if opts.words:
        chunks=[]
        for i,word in enumerate(opts.words):
            chunks.append(os.fsencode(word))
            if i+1 < len(opts.words):
                chunks.append(b' ' if word else b'\n')
        data=b''.join(chunks)
    elif data is None:
        data=sys.stdin.buffer.read()
    return Renderer(font, opts).render(controls.process(data,opts))


def main():
    try:
        output=run(sys.argv[1:],None,sys.argv[0])
        sys.stdout.buffer.write(output.encode('utf-8','surrogateescape'))
    except Failure as e:
        sys.stderr.write(str(e))
        return 1
    except BrokenPipeError:
        return 0
    return 0


if __name__=='__main__':
    sys.exit(main())
